 public GameResources(string root,ImportContext? context=null){Context=context??new();Root=Path.GetFullPath(root);if(!Directory.Exists(Root))throw new DirectoryNotFoundException(Root);try{UsvfsObserved=Process.GetCurrentProcess().Modules.Cast<ProcessModule>().Any(m=>m.ModuleName.StartsWith("usvfs",StringComparison.OrdinalIgnoreCase));}catch{}Notes.Add("Resource root: "+Root+" / USVFS module observed: "+UsvfsObserved+" (not proof of active profile)");}
 public string PathFor(string rel){Context.Cancellation.ThrowIfCancellationRequested();rel=rel.Replace('\\',Path.DirectorySeparatorChar).Replace('/',Path.DirectorySeparatorChar);if(Path.IsPathRooted(rel)||rel.Split(Path.DirectorySeparatorChar).Any(x=>x==".."||x.Contains(':')||x.Contains('\0')||x.EndsWith(' ')||x.EndsWith('.')))throw new InvalidDataException("Unsafe resource path: "+rel);string path=Path.GetFullPath(Path.Combine(Root,rel));string walked=Root;foreach(string part in rel.Split(Path.DirectorySeparatorChar)){walked=Path.Combine(walked,part);if((File.Exists(walked)||Directory.Exists(walked))&&(File.GetAttributes(walked)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Resource reparse point rejected: "+rel);}if(!path.StartsWith(Root.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Resource escapes root");return path;}
 public string? Find(string rel){var p=PathFor(rel);if(File.Exists(p)){Track(rel,p,null,"Visible loose file (current process Data view)");return p;}rel=BsaArchive.Normalize(rel);if(rel.StartsWith("skse/",StringComparison.OrdinalIgnoreCase))return null;foreach(string archive in archives.AsEnumerable().Reverse()){
