 public IEnumerable<string> EnumerateResources(string folder,string extension,bool recursive){
  string directory=PathFor(folder);string prefix=BsaArchive.Normalize(folder).TrimEnd('/')+"/";var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  if(Directory.Exists(directory))foreach(string file in Directory.EnumerateFiles(directory,"*"+extension,new EnumerationOptions{RecurseSubdirectories=recursive,MaxRecursionDepth=16,AttributesToSkip=FileAttributes.ReparsePoint,IgnoreInaccessible=false})){names.Add(Path.GetRelativePath(Root,file).Replace('\\','/'));if(names.Count>10000)throw new InvalidDataException("Resource enumeration budget");}
  foreach(string archive in archives){if(prefix.StartsWith("skse/",StringComparison.OrdinalIgnoreCase)||!CouldContain(archive,prefix))continue;var index=Index(archive);if(index==null)continue;foreach(string name in index.Entries.Keys)if(name.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)&&name.EndsWith(extension,StringComparison.OrdinalIgnoreCase)&&(recursive||!name[prefix.Length..].Contains('/'))){names.Add(name);if(names.Count>10000)throw new InvalidDataException("Resource enumeration budget");}}
  return names.OrderBy(n=>n,StringComparer.OrdinalIgnoreCase).ToList();
 }
 public IEnumerable<string> EnumerateBounded(string folder,string extension,int depth,int limit){
  var found=new HashSet<string>(StringComparer.OrdinalIgnoreCase);string prefix=BsaArchive.Normalize(folder).TrimEnd('/')+"/";
  var pending=new Queue<(string Dir,int Depth)>();pending.Enqueue((PathFor(folder),0));int visited=0;
  while(pending.TryDequeue(out var item)&&visited++<128&&found.Count<limit){Context.Cancellation.ThrowIfCancellationRequested();if(!Directory.Exists(item.Dir))continue;foreach(string f in Directory.EnumerateFiles(item.Dir,"*"+extension).Take(limit-found.Count))found.Add(Path.GetRelativePath(Root,f).Replace('\\','/'));if(item.Depth<depth)foreach(string d in Directory.EnumerateDirectories(item.Dir).Take(128))if((File.GetAttributes(d)&FileAttributes.ReparsePoint)==0)pending.Enqueue((d,item.Depth+1));}
  foreach(string archive in archives){if(prefix.StartsWith("skse/",StringComparison.OrdinalIgnoreCase)||!CouldContain(archive,prefix))continue;var index=Index(archive);if(index==null)continue;foreach(string name in index.Entries.Keys)if(name.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)&&name.EndsWith(extension,StringComparison.OrdinalIgnoreCase)&&name[prefix.Length..].Count(c=>c=='/')<=depth){found.Add(name);if(found.Count>=limit)break;}if(found.Count>=limit)break;}
  return found.OrderBy(x=>x,StringComparer.OrdinalIgnoreCase).Take(limit).ToList();
 }
 readonly Dictionary<string,(long Size,long Time)> pluginMetadata=new(StringComparer.OrdinalIgnoreCase);
 void Track(string rel,string selected,string? archive,string reason){rel=rel.Replace('\\','/');dependencyPaths[rel]=selected;if(!origins.ContainsKey(rel)){bool plugin=ValidPlugin(Path.GetFileName(rel));var info=new FileInfo(selected);if(info.Length>(plugin?2L*1024*1024*1024:128L*1024*1024))throw new InvalidDataException("Resource size budget: "+rel);if(plugin)pluginMetadata[rel]=(info.Length,info.LastWriteTimeUtc.Ticks);origins[rel]=new(rel,selected,BackingPath(archive??selected),archive,reason+(plugin?"; plugin metadata only until selected by an effective record":""),plugin?"":ImportFiles.Digest(selected));}}
 public void BindHeadPartEvidence(IEnumerable<HeadPartRecords.Record> records){var material=new StringBuilder(EnvironmentKey);foreach(var record in records.Where(r=>!r.Generated).OrderBy(r=>r.Id,StringComparer.OrdinalIgnoreCase)){material.Append('|').Append(record.Id).Append(':').Append(record.Source);foreach(var field in record.Fields){material.Append(field.type).Append(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(field.data)));}if(origins.TryGetValue(record.Source,out var source)&&source.Sha256.Length==0)origins[record.Source]=source with{Sha256=ImportFiles.Digest(source.Selected),Reason="Effective HeadPart source plugin (content verified)"};}EnvironmentKey=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(material.ToString())));}
 public void VerifyCurrent(){Context.Cancellation.ThrowIfCancellationRequested();foreach(var item in environmentFiles)if(!File.Exists(item.Key)||ImportFiles.Digest(item.Key)!=item.Value)throw new IOException("Active resource environment changed during loading; retry required.");var archiveChecks=new Dictionary<string,BsaArchive>(StringComparer.OrdinalIgnoreCase);foreach(var item in origins.Values.ToList()){Context.Cancellation.ThrowIfCancellationRequested();string actual;if(item.Sha256.Length==0){if(!File.Exists(item.Selected)||!pluginMetadata.TryGetValue(item.Logical,out var proof)||new FileInfo(item.Selected).Length!=proof.Size||File.GetLastWriteTimeUtc(item.Selected).Ticks!=proof.Time)throw new IOException("Plugin environment changed during loading");continue;}if(item.Archive==null)actual=ImportFiles.Digest(item.Selected);else{if(!archiveChecks.TryGetValue(item.Archive,out var archive))archiveChecks[item.Archive]=archive=new BsaArchive(item.Archive,Context.Cancellation);if(!archive.Entries.TryGetValue(BsaArchive.Normalize(item.Logical),out var entry))throw new IOException("Archive entry changed during loading");actual=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(archive.Read(entry)));}if(actual!=item.Sha256)throw new IOException("Resource changed during loading: "+item.Logical);}}
 public bool AllowsPlugin(string plugin)=>!PluginOrderVerified||ActivePlugins.Contains(plugin,StringComparer.OrdinalIgnoreCase);
 public void Configure(IEnumerable<string> referencedPlugins){Context.Stage("environment");
  archives.Clear();ActivePlugins.Clear();PluginOrderVerified=false;string list=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Skyrim Special Edition","plugins.txt");
  if(UsvfsObserved&&File.Exists(list)&&new FileInfo(list).Length<1024*1024){ActivePlugins.AddRange(File.ReadLines(list).Where(l=>l.StartsWith('*')).Select(l=>l[1..].Trim()).Where(ValidPlugin).Distinct(StringComparer.OrdinalIgnoreCase));string backing=BackingPath(list);PluginOrderVerified=ActivePlugins.Count>0;PluginListSource=list+" -> "+backing;Notes.Add("Observed plugin list: "+list+" -> "+backing+"; MO2 profile backing verified: "+PluginOrderVerified);}
  if(PluginOrderVerified){var implicitPlugins=new[]{"Skyrim.esm","Update.esm","Dawnguard.esm","HearthFires.esm","Dragonborn.esm"}.Where(n=>File.Exists(PathFor(n))).ToList();ActivePlugins.RemoveAll(n=>implicitPlugins.Contains(n,StringComparer.OrdinalIgnoreCase));ActivePlugins.InsertRange(0,implicitPlugins);}
