  void Archive(string name){if(Path.GetFileName(name)!=name||!name.EndsWith(".bsa",StringComparison.OrdinalIgnoreCase))return;string path=PathFor(name);if(File.Exists(path)){archives.RemoveAll(p=>p.Equals(path,StringComparison.OrdinalIgnoreCase));archives.Add(path);}}
  string game=Path.GetDirectoryName(Root)!;EnginePath=File.Exists(Path.Combine(game,"SkyrimSE.exe"))?Path.Combine(game,"SkyrimSE.exe"):null;var inis=new[]{Path.Combine(game,"Skyrim.ini"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"My Games","Skyrim Special Edition","Skyrim.ini")};
  foreach(string ini in inis)if(File.Exists(ini)&&new FileInfo(ini).Length<1024*1024){string section="";foreach(string line in File.ReadLines(ini)){string text=line.Trim();if(text.StartsWith('['))section=text.Trim('[',']');int at=text.IndexOf('=');if(section.Equals("Archive",StringComparison.OrdinalIgnoreCase)&&at>0&&text[..at].StartsWith("sResourceArchiveList",StringComparison.OrdinalIgnoreCase))foreach(string name in text[(at+1)..].Split(','))Archive(name.Trim());}}
  // Explicit base-game defaults, used only when visible in this Data tree.
  if(archives.Count==0)foreach(string name in new[]{"Skyrim - Meshes0.bsa","Skyrim - Meshes1.bsa","Skyrim - Textures0.bsa","Skyrim - Textures1.bsa","Skyrim - Textures2.bsa","Skyrim - Textures3.bsa","Skyrim - Textures4.bsa","Skyrim - Textures5.bsa","Skyrim - Textures6.bsa","Skyrim - Textures7.bsa","Skyrim - Textures8.bsa"})Archive(name);
