 public static string? Detect(){foreach(var start in new[]{Environment.CurrentDirectory,AppContext.BaseDirectory}){for(var d=new DirectoryInfo(start);d!=null;d=d.Parent){if(File.Exists(Path.Combine(d.FullName,"Skyrim.esm")))return d.FullName;if(File.Exists(Path.Combine(d.FullName,"Data","Skyrim.esm")))return Path.Combine(d.FullName,"Data");string ini=Path.Combine(d.FullName,"ModOrganizer.ini");if(File.Exists(ini)&&new FileInfo(ini).Length<1024*1024){foreach(var l in File.ReadLines(ini))if(l.StartsWith("gamePath=",StringComparison.OrdinalIgnoreCase)){string path=l[9..].Trim();if(path.StartsWith("@ByteArray(")&&path.EndsWith(')'))path=path[11..^1];path=path.Replace("\\\\","\\");if(Directory.Exists(Path.Combine(path,"Data")))return Path.Combine(path,"Data");}}}}return null;}
